insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('8786224d-e524-4337-bf16-0cc475eb3031', 'N2', '普通形（Aな・である／Nである） ＋ ばかりに', 'Chỉ vì...mà... (hậu quả không mong muốn xảy ra chỉ vì 1 lý do nhỏ)', NULL, '普通形（Aな・である／Nである） ＋ ばかりに', 'Diễn tả 1 hậu quả tiêu cực xảy ra chỉ vì 1 nguyên nhân nhỏ, thường mang sắc thái tiếc nuối', NULL, NULL, NULL, '{}', NULL, 64, '普通形（Aな・である／Nである） ＋ ばかりに', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('11cfd2c7-da37-485e-886f-7b257555f0fc', 'N2', 'Vる／Vない ＋ ものだ①', 'Vốn dĩ là.../Là đương nhiên... (chân lý, lẽ thường tình)', NULL, 'Vる／Vない ＋ ものだ', 'Diễn tả 1 sự thật hiển nhiên/lẽ thường tình mà ai cũng công nhận', NULL, NULL, NULL, '{}', NULL, 64, 'Vる／Vない ＋ ものだ①', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('cef5754d-f67e-4037-b1e3-07609c7f0838', 'N2', 'Vる ＋ ものだ②／ものではない', 'Nên.../Không nên... (lời khuyên mang tính đạo đức/chuẩn mực xã hội)', NULL, 'Vる ＋ ものだ／ものではない', 'Đưa ra lời khuyên/quy tắc đạo đức nên hay không nên làm gì', NULL, NULL, NULL, '{}', NULL, 64, 'Vる ＋ ものだ②／ものではない', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('ee69c0de-a431-418e-83c0-5c47d32fe183', 'N2', 'V(普)／Aい(普)／Aな ＋ ものだ③', 'Thật là...biết bao/Quả là...biết bao (cảm thán)', NULL, 'V(普)／Aい(普)／Aな ＋ ものだ', 'Diễn tả cảm xúc cảm thán trước 1 sự việc/trạng thái nào đó', NULL, NULL, NULL, '{}', NULL, 64, 'V(普)／Aい(普)／Aな ＋ ものだ③', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('43f63460-902f-426d-9cbb-581d8195e4af', 'N2', 'V普／Aい／N／Aな ＋ というものだ', 'Thật là, đúng là... (nhận định/đánh giá chung mang tính khẳng định)', NULL, 'V普／Aい／N／Aな ＋ というものだ', 'Đưa ra nhận định/đánh giá chung về 1 sự việc, nhấn mạnh đó là điều hiển nhiên đúng', NULL, NULL, NULL, '{}', NULL, 64, 'V普／Aい／N／Aな ＋ というものだ', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('0ca2a979-cf98-4a36-91e7-adb2943ea64d', 'N2', 'V(普)／Aい(普)／Aな／Aなである／Nである ＋ ものの', 'Mặc dù...nhưng.../thế mà... (nghịch với dự đoán/mong đợi)', NULL, 'V(普)／Aい(普)／Aな／Aなである／Nである ＋ ものの', 'Nêu 1 sự việc đã xảy ra rồi nêu kết quả trái ngược/không như mong đợi', NULL, NULL, NULL, '{}', NULL, 64, 'V(普)／Aい(普)／Aな／Aなである／Nである ＋ ものの', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('377c8443-ce59-403d-a86e-8768ce4fc3a0', 'N2', 'Vる(可能形) ＋ ものなら', 'Nếu như có thể... (giả định 1 điều khó/không thể xảy ra)', NULL, 'Vる(thể khả năng) ＋ ものなら', 'Đưa ra giả định về 1 việc thực tế khó/không thể thực hiện được', NULL, NULL, NULL, '{}', NULL, 64, 'Vる(可能形) ＋ ものなら', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('e6eaab40-ebb0-432c-89f3-e10e8e89d7d2', 'N2', '普通形N／Aな(だ) ＋ というものでは(も)ない', 'Tôi nghĩ rằng không phải hẳn là... (phủ định 1 quan niệm phổ biến)', NULL, '普通形N／Aな(だ) ＋ というものでは(も)ない', 'Phủ định lại 1 quan niệm/suy nghĩ phổ biến, cho rằng nó không hẳn đúng trong mọi trường hợp', NULL, NULL, NULL, '{}', NULL, 64, '普通形N／Aな(だ) ＋ というものでは(も)ない', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('3c6fabb0-85e9-44cd-8e71-ba0c6847e928', 'N2', 'Vる／Aい／Aな ＋ ものがある', 'Có điều gì đó cảm thấy rất... (cảm nhận chủ quan khó diễn tả cụ thể)', NULL, 'Vる／Aい／Aな ＋ ものがある', 'Diễn tả cảm nhận có 1 điều gì đó (khó nói cụ thể là gì) khiến người nói cảm thấy như vậy', NULL, NULL, NULL, '{}', NULL, 64, 'Vる／Aい／Aな ＋ ものがある', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('79d5812b-6434-4c4f-98d0-0d55c2d8bc13', 'N2', 'Vる／Aい／Aな ＋ ことになる／ことになっている', '① Sẽ, phải, đã được quyết định... (theo quy định/quyết định khách quan)　② Kết quả là... (kết luận suy ra từ tình huống)', NULL, NULL, NULL, NULL, NULL, NULL, '{}', NULL, 64, 'Vる／Aい／Aな ＋ ことになる／ことになっている', 'pdf', 'ok')
insert into jp_grammar_usages (id, grammar_id, usage_no, meaning, connection, usage, notes, source_page, source_type) values ('9357d339-25eb-4aca-91b1-c0bc084ece6d', '79d5812b-6434-4c4f-98d0-0d55c2d8bc13', 1, 'Sẽ, phải, đã được quyết định... (theo quy định/lịch trình/quyết định khách quan, không phải ý chí cá nhân)', 'Vる ＋ ことになっている', 'Nêu 1 quy định/lịch trình/thỏa thuận đã được xác lập từ trước', NULL, 64, 'pdf');
insert into jp_grammar_usages (id, grammar_id, usage_no, meaning, connection, usage, notes, source_page, source_type) values ('d2dfbecf-24c2-44bd-b0d8-4292e9c21466', '79d5812b-6434-4c4f-98d0-0d55c2d8bc13', 2, 'Kết quả là... (kết luận tự nhiên suy ra từ tình huống/diễn biến hiện tại)', 'Vる ＋ ことになる', 'Suy luận ra 1 kết quả tất yếu sẽ xảy ra dựa trên tình huống hiện tại', NULL, 64, 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('8786224d-e524-4337-bf16-0cc475eb3031', NULL, 1, 'standard', '財布を忘れたばかりに、電車に乗ることができず、遅刻してしまった。', 'Chỉ vì tôi để quên ví mà không thể lên tàu, nên đã bị muộn.', '財布を忘れた＿＿＿、電車に乗ることができず、遅刻してしまった。', 'ばかりに', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('8786224d-e524-4337-bf16-0cc475eb3031', NULL, 2, 'daily', '一言余計なことを言ったばかりに、友達を怒らせてしまった。', 'Chỉ vì lỡ nói thừa một câu mà tôi đã làm bạn mình tức giận.', '一言余計なことを言った＿＿＿、友達を怒らせてしまった。', 'ばかりに', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('8786224d-e524-4337-bf16-0cc475eb3031', NULL, 3, 'daily', '道に迷ったばかりに、大切な会議に遅れてしまった。', 'Chỉ vì bị lạc đường mà tôi đã đến muộn cuộc họp quan trọng.', '道に迷った＿＿＿、大切な会議に遅れてしまった。', 'ばかりに', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('11cfd2c7-da37-485e-886f-7b257555f0fc', NULL, 1, 'standard', '人前で演説する時は、誰でも緊張するものだ。', 'Khi diễn thuyết trước mọi người ai mà chẳng căng thẳng.', '人前で演説する時は、誰でも緊張する＿＿＿。', 'ものだ', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('11cfd2c7-da37-485e-886f-7b257555f0fc', NULL, 2, 'daily', '年を取れば、誰でも体が弱くなるものだ。', 'Khi về già, ai cũng đương nhiên yếu đi.', '年を取れば、誰でも体が弱くなる＿＿＿。', 'ものだ', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('11cfd2c7-da37-485e-886f-7b257555f0fc', NULL, 3, 'daily', '子供は親の背中を見て育つものだ。', 'Con cái vốn dĩ lớn lên nhìn theo tấm gương của cha mẹ.', '子供は親の背中を見て育つ＿＿＿。', 'ものだ', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('cef5754d-f67e-4037-b1e3-07609c7f0838', NULL, 1, 'standard', '知らない人の話を簡単に信用するものではない。', 'Không nên tin tưởng vào những lời nói của những người không quen biết.', '知らない人の話を簡単に信用する＿＿＿。', 'ものではない', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('cef5754d-f67e-4037-b1e3-07609c7f0838', NULL, 2, 'daily', '目上の人にはきちんと挨拶をするものだ。', 'Nên chào hỏi đàng hoàng với người bề trên.', '目上の人にはきちんと挨拶をする＿＿＿。', 'ものだ', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('cef5754d-f67e-4037-b1e3-07609c7f0838', NULL, 3, 'daily', '人の悪口を言うものではない。', 'Không nên nói xấu người khác.', '人の悪口を言う＿＿＿。', 'ものではない', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('ee69c0de-a431-418e-83c0-5c47d32fe183', NULL, 1, 'standard', '一度にあれほど多くの服を買うなんて贅沢なものだな。', 'Trong một lần mà mua nhiều quần áo đến mức đó thật là hoang phí.', '一度にあれほど多くの服を買うなんて贅沢な＿＿＿な。', 'ものだ', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('ee69c0de-a431-418e-83c0-5c47d32fe183', NULL, 2, 'daily', '子供の成長は早いものだ。', 'Sự trưởng thành của trẻ con thật là nhanh chóng.', '子供の成長は早い＿＿＿。', 'ものだ', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('ee69c0de-a431-418e-83c0-5c47d32fe183', NULL, 3, 'daily', '久しぶりに故郷に帰ると懐かしいものだ。', 'Lâu lắm mới về quê, thật là cảm thấy hoài niệm.', '久しぶりに故郷に帰ると懐かしい＿＿＿。', 'ものだ', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('43f63460-902f-426d-9cbb-581d8195e4af', NULL, 1, 'standard', '女性に年齢を聞くのはタブーというものだ。', 'Việc hỏi tuổi phụ nữ là điều cấm kỵ.', '女性に年齢を聞くのはタブー＿＿＿。', 'というものだ', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('43f63460-902f-426d-9cbb-581d8195e4af', NULL, 2, 'daily', '一人で全部やろうとするのは無理というものだ。', 'Muốn một mình làm hết tất cả thì đúng là vô lý.', '一人で全部やろうとするのは無理＿＿＿。', 'というものだ', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('43f63460-902f-426d-9cbb-581d8195e4af', NULL, 3, 'daily', '失敗を恐れて何もしないのはもったいないというものだ。', 'Sợ thất bại mà không làm gì cả thì thật là phí phạm.', '失敗を恐れて何もしないのはもったいない＿＿＿。', 'というものだ', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('0ca2a979-cf98-4a36-91e7-adb2943ea64d', NULL, 1, 'standard', 'せっかくマフラーを編んだものの、彼に渡すチャンスがなかった。', 'Mặc dù đã mất công đan khăn len nhưng cuối cùng cũng không có cơ hội tặng cho anh ấy.', 'せっかくマフラーを編んだ＿＿＿、彼に渡すチャンスがなかった。', 'ものの', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('0ca2a979-cf98-4a36-91e7-adb2943ea64d', NULL, 2, 'daily', '頑張って勉強したものの、試験に落ちてしまった。', 'Mặc dù đã cố gắng học hành nhưng tôi vẫn trượt kỳ thi.', '頑張って勉強した＿＿＿、試験に落ちてしまった。', 'ものの', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('0ca2a979-cf98-4a36-91e7-adb2943ea64d', NULL, 3, 'daily', '医者に止められたものの、彼はタバコをやめられない。', 'Mặc dù bị bác sĩ ngăn cản nhưng anh ấy vẫn không thể bỏ thuốc lá.', '医者に止められた＿＿＿、彼はタバコをやめられない。', 'ものの', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('377c8443-ce59-403d-a86e-8768ce4fc3a0', NULL, 1, 'standard', '学生時代に戻れるものなら、真面目に勉強をしたい。', 'Nếu như có thể quay trở lại thời học sinh tôi muốn học hành chăm chỉ.', '学生時代に戻れる＿＿＿、真面目に勉強をしたい。', 'ものなら', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('377c8443-ce59-403d-a86e-8768ce4fc3a0', NULL, 2, 'daily', 'できるものなら、彼を助けてあげたい。', 'Nếu có thể thì tôi muốn giúp đỡ anh ấy.', 'できる＿＿＿、彼を助けてあげたい。', 'ものなら', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('377c8443-ce59-403d-a86e-8768ce4fc3a0', NULL, 3, 'daily', '行けるものなら、来週の旅行に参加したい。', 'Nếu có thể đi được thì tôi muốn tham gia chuyến du lịch tuần sau.', '行ける＿＿＿、来週の旅行に参加したい。', 'ものなら', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('e6eaab40-ebb0-432c-89f3-e10e8e89d7d2', NULL, 1, 'standard', '結婚したからといって幸せだというものでもない。', 'Tôi nghĩ rằng không phải kết hôn xong là hạnh phúc đâu.', '結婚したからといって幸せだ＿＿＿。', 'というものでもない', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('e6eaab40-ebb0-432c-89f3-e10e8e89d7d2', NULL, 2, 'daily', 'お金があれば幸せだというものではない。', 'Không phải cứ có tiền là hạnh phúc.', 'お金があれば幸せだ＿＿＿。', 'というものではない', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('e6eaab40-ebb0-432c-89f3-e10e8e89d7d2', NULL, 3, 'daily', '高ければいいというものでもない。', 'Không phải cứ đắt là tốt.', '高ければいい＿＿＿。', 'というものでもない', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('3c6fabb0-85e9-44cd-8e71-ba0c6847e928', NULL, 1, 'standard', '彼の演説は何か人の心を動かすものがある。', 'Bài diễn thuyết của anh ấy có điều gì đó thôi thúc trái tim của mọi người.', '彼の演説は何か人の心を動かす＿＿＿。', 'ものがある', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('3c6fabb0-85e9-44cd-8e71-ba0c6847e928', NULL, 2, 'daily', 'この曲には人を悲しくさせるものがある。', 'Bài hát này có điều gì đó khiến người ta buồn.', 'この曲には人を悲しくさせる＿＿＿。', 'ものがある', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('3c6fabb0-85e9-44cd-8e71-ba0c6847e928', NULL, 3, 'daily', '彼女の笑顔には人を安心させるものがある。', 'Nụ cười của cô ấy có điều gì đó khiến người ta an tâm.', '彼女の笑顔には人を安心させる＿＿＿。', 'ものがある', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('79d5812b-6434-4c4f-98d0-0d55c2d8bc13', '9357d339-25eb-4aca-91b1-c0bc084ece6d', 1, 'standard', 'この図書館は休日は8時で閉館することになっている。', 'Thư viện này vào ngày nghỉ sẽ đóng cửa lúc 8 giờ.', 'この図書館は休日は8時で閉館する＿＿＿。', 'ことになっている', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('79d5812b-6434-4c4f-98d0-0d55c2d8bc13', '9357d339-25eb-4aca-91b1-c0bc084ece6d', 2, 'daily', '会議は来週の月曜日に行うことになっている。', 'Cuộc họp được quyết định sẽ tổ chức vào thứ hai tuần sau.', '会議は来週の月曜日に行う＿＿＿。', 'ことになっている', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('79d5812b-6434-4c4f-98d0-0d55c2d8bc13', '9357d339-25eb-4aca-91b1-c0bc084ece6d', 3, 'daily', 'この学校では、制服を着ることになっている。', 'Ở trường này, quy định là phải mặc đồng phục.', 'この学校では、制服を着る＿＿＿。', 'ことになっている', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('79d5812b-6434-4c4f-98d0-0d55c2d8bc13', 'd2dfbecf-24c2-44bd-b0d8-4292e9c21466', 1, 'standard', 'これ以上お客さんの数が減ってしまったら、このレストランも閉店することになるだろう。', 'Nếu lượng khách hàng còn giảm nhiều hơn mức này, chắc nhà hàng này sẽ phải đóng cửa thôi.', 'これ以上お客さんの数が減ってしまったら、このレストランも閉店する＿＿＿だろう。', 'ことになる', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('79d5812b-6434-4c4f-98d0-0d55c2d8bc13', 'd2dfbecf-24c2-44bd-b0d8-4292e9c21466', 2, 'daily', 'このままでは、彼は会社を辞めることになるかもしれない。', 'Cứ đà này, có lẽ anh ấy sẽ phải nghỉ việc ở công ty.', 'このままでは、彼は会社を辞める＿＿＿かもしれない。', 'ことになる', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('79d5812b-6434-4c4f-98d0-0d55c2d8bc13', 'd2dfbecf-24c2-44bd-b0d8-4292e9c21466', 3, 'daily', '準備を怠ると、試験に落ちることになる。', 'Nếu lơ là chuẩn bị thì kết quả là sẽ trượt kỳ thi.', '準備を怠ると、試験に落ちる＿＿＿。', 'ことになる', 'generated');
